#include <bits/stdc++.h>
using namespace std;

int main() {
    int n;
    if (!(cin >> n)) return 0;
    string line;
    getline(cin, line); // consume rest of first line
    long long bal = 0;
    bool ok = true;
    for (int i = 0; i < n; i++) {
        getline(cin, line);
        for (char c : line) {
            if (c == '{') bal++;
            else if (c == '}') {
                bal--;
                if (bal < 0) ok = false;
            }
        }
    }
    if (bal != 0) ok = false;
    cout << (ok ? "S" : "N") << "\n";
    return 0;
}
